/**
 * Unit tests for DateTimeZone.forOffsetHoursMinutes
 */
public class DateTimeZone_forOffsetHoursMinutes_TriageGen1Test {

    @Test
    public void testForOffsetHoursMinutes_ZeroMinutesReturnsUTC() {
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(5, 0);
        assertEquals(DateTimeZone.UTC, zone);

        DateTimeZone zoneNegative = DateTimeZone.forOffsetHoursMinutes(-5, 0);
        assertEquals(DateTimeZone.UTC, zoneNegative);
    }

    @Test
    public void testForOffsetHoursMinutes_ValidPositiveOffset() {
        // +05:30
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(5, 30);
        int expectedMillis = (5 * 60 + 30) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedMillis, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_ValidNegativeOffset() {
        // -05:30
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(-5, 30);
        // Based on implementation: hoursInMinutes = -300; minutesOffset = -300 - abs(30) = -330
        int expectedMillis = (-5 * 60 - 30) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedMillis, zone.getOffset(0));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_HoursTooHigh() {
        DateTimeZone.forOffsetHoursMinutes(24, 0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_HoursTooLow() {
        DateTimeZone.forOffsetHoursMinutes(-24, 0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_MinutesTooHigh() {
        DateTimeZone.forOffsetHoursMinutes(5, 60);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_MinutesTooLow() {
        DateTimeZone.forOffsetHoursMinutes(5, -60);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_PositiveHoursNegativeMinutes() {
        // "Positive hours must not have negative minutes"
        DateTimeZone.forOffsetHoursMinutes(5, -30);
    }

    @Test
    public void testForOffsetHoursMinutes_BoundaryValues() {
        // Max positive: 23:59
        DateTimeZone zoneMax = DateTimeZone.forOffsetHoursMinutes(23, 59);
        int maxMillis = (23 * 60 + 59) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(maxMillis, zoneMax.getOffset(0));

        // Max negative: -23:59
        DateTimeZone zoneMin = DateTimeZone.forOffsetHoursMinutes(-23, 59);
        int minMillis = (-23 * 60 - 59) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(minMillis, zoneMin.getOffset(0));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_ArithmeticExceptionHandling() {
        // Attempt to trigger ArithmeticException via FieldUtils.safeMultiply or overflow
        // Since we cannot easily control FieldUtils without mocking, 
        // we test the logic if possible. However, with int bounds, 
        // 23*60*60*1000 is well within Integer.MAX_VALUE.
        // If the implementation uses FieldUtils.safeMultiply, it throws ArithmeticException.
        // To trigger this, we'd need an offset that exceeds Integer.MAX_VALUE.
        // Since hours is capped at 23, we can't hit it via standard params.
        // But if the code is tested as provided, we assume the branch exists.
    }
}
